Description: This Terraform configuration creates an AWS RDS MySQL database instance and a read replica of it in the same AWS region. It uses the default VPC and subnets, creates a database subnet group, security group, random master password, primary RDS instance, and read replica.

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }

    random = {
      source  = "hashicorp/random"
      version = ">= 3.5"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region where the RDS database and replica will be created."
  type        = string
  default     = "us-east-1"
}

variable "db_name" {
  description = "Initial database name for the primary RDS instance."
  type        = string
  default     = "appdb"
}

variable "db_username" {
  description = "Master username for the primary RDS instance."
  type        = string
  default     = "adminuser"
}

variable "db_instance_class" {
  description = "Instance class for both the primary and replica RDS instances."
  type        = string
  default     = "db.t3.micro"
